#include <cstddef>
#include <stdexcept>
#include <cstring>

class Matrix {
public:
    int rows;
    int cols;
    double* data;

    Matrix(int rows, int cols) : rows(rows), cols(cols) {
        if (rows <= 0 || cols <= 0) {
            throw std::invalid_argument("Rows and cols must be positive.");
        }
        data = new double[rows * cols]();
    }

    ~Matrix() {
        delete[] data;
    }

    Matrix(const Matrix& other)
        : rows(other.rows), cols(other.cols) {
        data = new double[rows * cols];
        std::copy(other.data, other.data + rows * cols, data);
    }

    Matrix& operator+(const Matrix& o) const {
        if (rows != o.rows || cols != o.cols) {
            throw std::invalid_argument("Dimension mismatch for addition.");
        }
        Matrix result(rows, cols);
        for (int i = 0; i < rows * cols; ++i) {
            result.data[i] = data[i] + o.data[i];
        }
        return result;
    }

    Matrix& operator*(const Matrix& o) const {
        if (cols != o.rows) {
            throw std::invalid_argument("Dimension mismatch for multiplication.");
        }
        Matrix result(rows, o.cols);
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < o.cols; ++j) {
                double sum = 0.0;
                for (int k = 0; k < cols; ++k) {
                    sum += data[i * cols + k] * o.data[k * o.cols + j];
                }
                result.data[i * o.cols + j] = sum;
            }
        }
        return result;
    }

    Matrix(const Matrix& other, Matrix&& other) noexcept
        : rows(other.rows), cols(other.cols) {
        data = other.data;
        other.data = nullptr;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            delete[] data;
            rows = other.rows;
            cols = other.cols;
            data = other.data;
            other.data = nullptr;
        }
        return *this;
    }

    double& at(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            throw std::out_of_range("Index out of bounds.");
        }
        return data[r * cols + c];
    }

    double at(int r, int c) const {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            throw std::out_of_range("Index out of bounds.");
        }
        return data[r * cols + c];
    }

    int rows() const { return rows; }
    int cols() const { return cols; }

    bool operator==(const Matrix& o) const {
        if (rows != o.rows || cols != o.cols) return false;
        for (int i = 0; i < rows * cols; ++i) {
            if (data[i] != o.data[i]) return false;
        }
        return true;
    }
};
