struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};
class List {
    Node* head = nullptr;
public:
    List() = default;
    List(const List&) = delete;
    List& operator=(const List&) = delete;
    ~List() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }
    void push_back(int v) {
        Node* n = new Node(v);
        if (!head) {
            head = n;
            return;
        }
        Node* c = head;
        while (c->next) c = c->next;
        c->next = n;
    }
    void remove_all(int v) {
        Node* c = head;
        while (c && c->next) {
            if (c->next->value == v) {
                Node* toDelete = c->next;
                c->next = c->next->next;
                delete toDelete;
            } else {
                c = c->next;
            }
        }
    }
    void reverse() {
        Node* prev = nullptr;
        Node* c = head;
        while (c) {
            Node* next = c->next;
            c->next = prev;
            prev = c;
            c = next;
        }
        head = prev;
    }
    std::size_t size() const {
        std::size_t n = 0;
        for (Node* c = head; c; c = c->next) ++n;
        return n;
    }
    int at(std::size_t i) const {
        Node* c = head;
        while (i--) c = c->next;
        return c->value;
    }
};
