def topo_sort(graph):
    # Build in-degree and adjacency list, making a copy to avoid mutating the original
    in_degree = {}
    adj = {}
    for node in graph:
        in_degree[node] = 0
        adj[node] = []
    for node, deps in graph.items():
        for dep in deps:
            in_degree.setdefault(dep, 0)
            in_degree[dep] = in_degree.get(dep, 0) + 1
            adj.setdefault(dep, [])
            adj[dep].append(node)

    # Use a min-heap (priority queue) for lexicographically smallest ready node
    import heapq
    heap = [node for node in in_degree if in_degree[node] == 0]
    heapq.heapify(heap)
    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(in_degree):
        raise ValueError("Cycle detected")

    return result
