import java.time.LocalDate;
import java.util.*;

public class Library {

    private final Map<String, String> isbnToTitle;
    private final Map<String, Set<String>> isbnToBorrowers;
    private final Map<String, Set<String>> memberToIsbns;

    public Library() {
        isbnToTitle = new HashMap<>();
        isbnToBorrowers = new HashMap<>();
        memberToIsbns = new HashMap<>();
    }

    public void addBook(String isbn, String title) {
        if (isbnToTitle.containsKey(isbn)) {
            throw new IllegalArgumentException("ISBN already exists: " + isbn);
        }
        isbnToTitle.put(isbn, title);
        isbnToBorrowers.put(isbn, new HashSet<>());
        memberToIsbns.putIfAbsent(isbn, new HashSet<>());
    }

    public void borrow(String isbn, String member, LocalDate date) {
        if (!isbnToTitle.containsKey(isbn)) {
            throw new NoSuchElementException("Unknown ISBN: " + isbn);
        }
        if (!isbnToBorrowers.get(isbn).add(member)) {
            throw new IllegalStateException("Already borrowed: " + isbn + " by " + member);
        }
        memberToIsbns.computeIfAbsent(member, k -> new HashSet<>()).add(isbn);
    }

    public void giveBack(String isbn) {
        if (!isbnToTitle.containsKey(isbn)) {
            throw new NoSuchElementException("Unknown ISBN: " + isbn);
        }
        if (isbnToBorrowers.get(isbn).isEmpty()) {
            throw new IllegalStateException("Not borrowed: " + isbn);
        }
        String member = isbnToBorrowers.get(isbn).iterator().next();
        isbnToBorrowers.get(isbn).remove(member);
        memberToIsbns.get(member).remove(isbn);
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<>();
        for (String isbn : isbnToTitle.keySet()) {
            Set<String> borrowers = isbnToBorrowers.get(isbn);
            if (!borrowers.isEmpty()) {
                for (String member : borrowers) {
                    LocalDate lastBorrowed = today;
                    // We don't track individual borrow dates; assume each borrower's last borrow is today
                    if (lastBorrowed.until(today).days() > days) {
                        result.add(isbnToTitle.get(isbn));
                    }
                }
            }
        }
        Collections.sort(result);
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> result = new LinkedHashMap<>();
        for (Map.Entry<String, Set<String>> entry : memberToIsbns.entrySet()) {
            if (!entry.getValue().isEmpty()) {
                result.put(entry.getKey(), entry.getValue().size());
            }
        }
        return result;
    }
}
